parameters.jsCode:
// ============================================================================
// NORMALIZAR DADOS CADASTRAIS — duas fontes Econodata, papeis diferentes:
//
//   edMat (MATRIZ)  -> tudo que e pontuado / economico:
//                      faturamento anual estimado, regime tributario, capital
//                      social, data de abertura, porte, qtd funcionarios/filiais,
//                      divida ativa da Uniao (PGFN) e divida dos socios.
//   edFil (FILIAL)  -> identidade do estabelecimento consultado:
//                      uf, cidade, situacao cadastral, nome fantasia.
//                      (a UF da filial e o que alimenta a CND Estadual)
//
// Para filial o Econodata devolve capitalSocial / quantidadeFuncionarios /
// dividasResumo = null e dataAbertura da FILIAL — por isso a 2a chamada existe.
// ============================================================================

const edMat = $('Econodata Matriz (Resultado)').first().json ?? {};
const edFil = $('Econodata · Empresa (Consultado)').first().json ?? {};
const d1    = $('Executar D1 (Coleta Fiscal)').first().json ?? {};
const f     = $('Buscar Fornecedor').first().json;
const qsa   = $('Direct Data · QSA e Participação Societária').first().json.retorno ?? {};
const hist  = $('Agregar Histórico Sócios').first().json ?? {};

function classificarRegime(v) {
  const s = String(v ?? '').toLowerCase();
  if (!s) return 'ND';
  if (s.includes('mei') || s.includes('microempreendedor')) return 'MEI';
  if (s.includes('simples')) {
    // A tabela de pontos tem uma faixa própria (85 pts) para o Simples que optou
    // pelo regime regular de IBS/CBS — ela só é alcançada se a fonte informar isso.
    return /regular|opc|opç/.test(s)
      ? 'Simples Nacional - opção regime regular'
      : 'Simples Nacional (padrão)';
  }
  if (s.includes('real') || s.includes('arbitrado')) return 'Lucro Real (regime regular IBS/CBS)';
  if (s.includes('presumido')) return 'Lucro Presumido';
  if (s.includes('imune') || s.includes('isent')) return 'Imune/Isento/Não contribuinte';
  return 'ND';
}

function numDecimal(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
  const v = parseFloat(String(raw).replace(/[^\d.-]/g, ''));
  return Number.isFinite(v) ? v : null;
}

function extrairCapitalSocialQSA(texto) {
  if (!texto) return null;
  const match = String(texto).match(/[\d.,]+/);
  if (!match) return null;
  const num = match[0].replace(/\./g, '').replace(',', '.');
  const valor = parseFloat(num);
  return Number.isFinite(valor) ? valor : null;
}

// Extrai o(s) numero(s) de uma faixa em texto ("R$ 1.800.001 a R$ 4.800.000")
// e retorna o maior valor (teto da faixa).
function parseFaixaMax(raw) {
  if (raw === null || raw === undefined) return null;
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : null;
  const matches = String(raw).match(/[\d.,]+/g);
  if (!matches || matches.length === 0) return null;
  const valores = matches
    .map(m => {
      const s = m.replace(/\./g, '').replace(',', '.'); // BR: ponto=milhar, virgula=decimal
      const v = parseFloat(s);
      return Number.isFinite(v) ? v : null;
    })
    .filter(v => v !== null);
  return valores.length > 0 ? Math.max(...valores) : null;
}

// data de abertura da MATRIZ (a da filial nao serve para longevidade)
function dataFundacao() {
  if (edMat.dataAbertura) return String(edMat.dataAbertura).slice(0, 10);
  if (qsa.dataAbertura) return String(qsa.dataAbertura).split(' ')[0].split('/').reverse().join('-');
  if (edFil.dataAbertura) return String(edFil.dataAbertura).slice(0, 10);
  return null;
}

const porte = edMat.porteEstimado
  ?? (Array.isArray(edMat.enquadramentoPorte) ? edMat.enquadramentoPorte[0] : null)
  ?? edFil.porteEstimado
  ?? null;

// ---------------------------------------------------------------------------
// FATURAMENTO — decisao BMS: faturamento da MATRIZ (a propria PJ), nao do
// grupo economico. O grupo economico so entra como ultimo recurso, porque
// infla o denominador da Dependencia de Faturamento (D4) e derruba a
// sensibilidade do indicador.
// ---------------------------------------------------------------------------
const faturamento_estimado =
     parseFaixaMax(edMat.faturamentoPresumidoGrupoEconomico)
  ?? parseFaixaMax(edMat.faturamentoAnualPresumido ?? edMat.faturamentoPresumido)
  ?? null;

return [{
  json: {
    fornecedor_id: f.fornecedor_id,

    // ---- identificacao / matriz -------------------------------------------
    cnpj_matriz:  d1.cnpj_matriz ?? null,
    eh_filial:    (d1.eh_filial === true || d1.eh_filial === 'true'),
    matriz_fonte: d1.matriz_fonte ?? null,

    // ---- estabelecimento consultado (FILIAL) ------------------------------
    uf:                 edFil.uf     ?? f.uf ?? null,
    cidade:             edFil.cidade ?? f.cidade ?? null,
    situacao_cadastral: edFil.situacao ?? null,
    nome_fantasia:      edFil.nomeFantasia ?? edMat.nomeFantasia ?? null,

    // ---- MATRIZ (base de tudo que pontua) ---------------------------------
    razao_social:      edMat.razaoSocial ?? edFil.razaoSocial ?? f.razao_social ?? null,
    regime_tributario: classificarRegime(edMat.regime_tributario ?? edFil.regime_tributario),
    porte,
    faturamento_estimado,
    data_fundacao:  dataFundacao(),
    capital_social: numDecimal(edMat.capitalSocial) ?? extrairCapitalSocialQSA(qsa.capitalSocialQSA),
    qtd_funcionarios: edMat.quantidadeFuncionarios ?? null,
    qtd_filiais:      edMat.quantidadeFiliais ?? null,

    em_recuperacao_judicial: qsa.emRecuperacaoJudicial === true ? true : null,
    pct_problematico_socios: hist.pct_problematico_medio ?? null,
    detalhes_socios:         hist.detalhes_socios ?? null,

    // ---- divida ativa da Uniao (PGFN) — SEMPRE da matriz ------------------
    divida_uniao_total:           edMat.dividasResumo?.dividas_uniao?.total_dividas_principal ?? null,
    divida_uniao_qtde:            edMat.dividasResumo?.dividas_uniao?.qtde_dividas_principal ?? null,
    divida_uniao_pct_faturamento: edMat.dividasResumo?.dividas_uniao?.percentual_faturamento_principal ?? null,
    divida_uniao_socios_total:    edMat.dividasResumoSocios?.dividas_uniao?.total_dividas_principal ?? null
  }
}];

