parameters.jsCode:
const dados = $('Buscar Tabelas de Pontos').first().json;
const tabelas = dados.tabelas_pontos || {};
const fonte = $('Buscar Fonte de Reaproveitamento').first().json.fonte;

// A tabela de pontos é editável no portal, então o rótulo de "sem dado" varia:
// 'ND' no spc/sintonia, 'Não obtida' no cnd_federal, 'Não verificado' no pgfn.
// O código sempre emite 'ND', então precisamos reconhecer os equivalentes —
// senão a categoria não casa e o critério cai em 0 pontos em vez do valor de ND.
const ND_SINONIMOS = ['ND', 'Não obtida', 'Não verificado', 'Não informado', 'Não emitida', 'Não localizado'];

function chaveNormalizada(s) {
  return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
}

function chaveNdDaTabela(t) {
  return Object.keys(t).find((k) =>
    ND_SINONIMOS.some((s) => chaveNormalizada(s) === chaveNormalizada(k)));
}

function pontosOpcao(criterio, categoria) {
  const t = tabelas[criterio];
  if (!t) return 0;
  if (categoria in t) return Number(t[categoria]);

  // 2ª tentativa: casa ignorando acento e caixa (protege contra divergência de grafia)
  const alvo = chaveNormalizada(categoria);
  const kExato = Object.keys(t).find((k) => chaveNormalizada(k) === alvo);
  if (kExato) return Number(t[kExato]);

  // fallback: qualquer rótulo que signifique "sem dado"
  const kNd = chaveNdDaTabela(t);
  return kNd ? Number(t[kNd]) : 0;
}

function pontosBanda(criterio, valor) {
  const t = tabelas[criterio];
  if (!t || !t.bands || t.bands.length === 0) return 0;
  if (valor === 'ND' || valor === null || valor === undefined) return Number(t.nd_pontos ?? 0);
  const num = Number(valor);
  if (!Number.isFinite(num)) return Number(t.nd_pontos ?? 0);

  const isMinType = 'min' in t.bands[0];
  if (isMinType) {
    const sorted = [...t.bands].sort((a, b) => Number(b.min) - Number(a.min));
    for (const b of sorted) {
      if (num >= Number(b.min)) return Number(b.pontos);
    }
  } else {
    for (const b of t.bands) {
      if (b.max === null || b.max === undefined || num <= b.max) return Number(b.pontos);
    }
  }
  return Number(t.nd_pontos ?? 0);
}

const INFO_INDICADOR = {
  cnd_federal: { rotulo: 'CND/CPEN Federal', dimensao: 'D1', fonte: 'Receita Federal e PGFN, via Infosimples (CNPJ da matriz)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'A Receita Federal não conseguiu emitir a certidão online para o CNPJ da matriz (normalmente cadastro incompleto no órgão).', o_que_resolve: 'Reconsultar raramente resolve — depende do cadastro na Receita Federal.', efeito_texto: 'Se vier "Negativa", o D1 sobe significativamente. Sem a certidão, a classificação do PGFN também fica presumida.' },
  pgfn: { rotulo: 'Dívida ativa PGFN', dimensao: 'D1', fonte: 'Econodata — dívida ativa da União (CNPJ da matriz) + certidão federal via Infosimples', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'O Econodata registra dívida ativa da União, mas a certidão federal não foi emitida — sem ela não é possível saber se o débito está exigível ou regularizado (parcelado ou garantido).', o_que_resolve: 'Reconsultar pode resolver: se a certidão for emitida, a classificação deixa de ser presumida.', efeito_texto: 'Hoje classificado no grau mais brando (Parcelada/garantida) para não penalizar falha de coleta. Se a certidão vier negativa, o D1 sobe; se vier positiva pura, cai e pode disparar o Gate G3.' },
  sintonia: { rotulo: 'Conformidade RFB (Sintonia/Confia)', dimensao: 'D1', fonte: 'Receita Federal — Selo Sintonia (consulta pública) e lista de protocolos do Confia', motivo_tipo: 'NAO_LOCALIZADO', motivo: 'A empresa não está na lista pública do selo A+ nem entre os protocolos do Confia; os graus A, B, C e D exigem login do próprio fornecedor no e-CAC.', o_que_resolve: 'Só o próprio fornecedor confirma o grau — não há consulta pública para isso.', efeito_texto: 'Se tiver selo A+ ou protocolo Confia ativo, o D1 sobe.' },
  regularidade_estadual_municipal: { rotulo: 'Regularidade estadual', dimensao: 'D1', fonte: 'SEFAZ estadual, via Direct Data (CNPJ e UF do estabelecimento)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'A consulta à SEFAZ do estado do estabelecimento não retornou resultado — alguns estados não expõem a certidão por API.', o_que_resolve: 'Reconsultar pode resolver — instabilidade momentânea é comum aqui.', efeito_texto: 'Se "Regular", o D1 sobe.' },
  obrigacoes_acessorias: { rotulo: 'Obrigações acessórias (Longevidade/Capital/Sócios)', dimensao: 'D1 · composta', fonte: 'Econodata — data de abertura e capital social da matriz + Direct Data — QSA e vínculos societários', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'Nenhum dos 3 índices que compõem esse subcritério (longevidade, capital social e histórico dos sócios) pôde ser calculado.', o_que_resolve: 'Reconsultar pode resolver, se foi falha temporária de uma das fontes.', efeito_texto: 'A nota é a média dos índices com dado; sem nenhum deles, o subcritério fica no valor de ND.' },
  serasa_score: { rotulo: 'Serasa Score', dimensao: 'D2', fonte: 'Serasa Experian — Relatório Intermediário PJ (score positivo)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'O relatório da Serasa não retornou o score.', o_que_resolve: 'Reconsultar pode resolver.', efeito_texto: 'Se o score vier alto, o D2 sobe bastante (é o maior peso de D2).' },
  protestos: { rotulo: 'Protestos', dimensao: 'D2', fonte: 'Serasa Experian — Relatório Intermediário PJ (protestos em cartório)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'O relatório da Serasa não trouxe a contagem de protestos.', o_que_resolve: 'Reconsultar pode resolver.', efeito_texto: 'Sem esse dado o critério fica em ND — não é lido como zero protestos.' },
  execucoes_relevantes: { rotulo: 'Execuções Relevantes', dimensao: 'D2', fonte: 'Serasa Experian — Relatório Intermediário PJ (ações judiciais)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'O relatório da Serasa não trouxe o bloco de ações judiciais.', o_que_resolve: 'Reconsultar pode resolver.', efeito_texto: 'Sem esse dado o critério fica em ND — não é lido como zero execuções.' },
  spc: { rotulo: 'Negativação SPC', dimensao: 'D2', fonte: 'Serasa Experian — anotações SPC do Relatório Intermediário PJ (janela de 12 meses)', motivo_tipo: 'FALHA_NA_CONSULTA', motivo: 'O relatório da Serasa não trouxe o bloco de anotações do SPC.', o_que_resolve: 'Reconsultar pode resolver.', efeito_texto: 'Consideramos apenas ocorrências dos 12 meses anteriores à análise; sem o dado, o critério fica em ND.' },
  faturamento_presumido: { rotulo: 'Faturamento anual estimado', dimensao: 'D2 · D4', fonte: 'Econodata — faturamento presumido do grupo econômico (CNPJ da matriz)', motivo_tipo: 'NAO_LOCALIZADO', motivo: 'O Econodata não trouxe faturamento presumido nem para o grupo econômico nem para a matriz.', o_que_resolve: 'Reconsultar não resolve — depende da base do Econodata. O analista pode informar o valor manualmente.', efeito_texto: 'Afeta o D2 e deixa o D4 sem denominador, que passa a usar nota neutra.' },
  regime_tributario: { rotulo: 'Regime Tributário', dimensao: 'D3', fonte: 'Econodata — cadastro da matriz (Receita Federal e Simples Nacional)', motivo_tipo: 'NAO_LOCALIZADO', motivo: 'O campo de regime tributário veio vazio no cadastro da matriz — ocorre até com empresas grandes e regulares (limitação conhecida da fonte).', o_que_resolve: 'Reconsultar não resolve — é limitação da fonte atual. O analista pode informar o regime manualmente.', efeito_texto: 'Se confirmado Lucro Real, o D3 vai a 100; em ND fica em 20.' },
  dependencia_faturamento: { rotulo: 'Dependência de Faturamento', dimensao: 'D4', fonte: 'Valor de compras informado pela BMS + faturamento presumido do grupo econômico (Econodata)', motivo_tipo: 'NAO_LOCALIZADO', motivo: 'Sem o faturamento estimado do fornecedor não há denominador para a fórmula de dependência.', o_que_resolve: 'Resolve-se automaticamente quando o faturamento presumido for obtido.', efeito_texto: 'Hoje usando valor neutro (50 pts) em vez do valor real da fórmula.' },
};

function pontosMaximoPossivel(criterio) {
  const t = tabelas[criterio];
  if (!t) return null;
  if (t.bands) return Math.max(...t.bands.map((b) => Number(b.pontos)));
  const kNd = chaveNdDaTabela(t);
  const valores = Object.entries(t)
    .filter(([k]) => k !== 'nd_pontos' && k !== kNd)
    .map(([, v]) => Number(v))
    .filter(Number.isFinite);
  return valores.length ? Math.max(...valores) : null;
}
function pontosNdAtual(criterio) {
  const t = tabelas[criterio];
  if (!t) return 0;
  if (t.nd_pontos != null) return Number(t.nd_pontos);
  const kNd = chaveNdDaTabela(t);
  return kNd ? Number(t[kNd]) : 0;
}

function montarIndicadorFaltante(criterio, pontosAtuaisReais) {
  const info = INFO_INDICADOR[criterio];
  if (!info) return null;
  const potenciais = pontosMaximoPossivel(criterio);
  const atuais = pontosAtuaisReais != null ? pontosAtuaisReais : pontosNdAtual(criterio);
  return {
    criterio, dimensao: info.dimensao, rotulo: info.rotulo, fonte: info.fonte,
    motivo_tipo: info.motivo_tipo, motivo: info.motivo, o_que_resolve: info.o_que_resolve, efeito_texto: info.efeito_texto,
    pontos_atuais: atuais, pontos_potenciais: potenciais,
    impacto_pontos: potenciais != null ? Math.round((potenciais - atuais) * 100) / 100 : null,
    impacto_texto: potenciais != null ? `${atuais} pts → até ${potenciais} pts` : null,
    acao: info.motivo_tipo === 'FALHA_NA_CONSULTA' ? 'Reconsultar' : 'Informar manualmente',
  };
}

let s1, s2, s3, s5;
let d1_block, d2_block, d3_block;
let camposND = [];
let indicadores_faltantes = [];

if (fonte) {
  // ---------- REAPROVEITADO: D1/D2/D3 vêm da análise de origem ----------
  s1 = Number(fonte.s1_fiscal ?? 0);
  s2 = Number(fonte.s2_financeira ?? 0);
  s3 = Number(fonte.s3_regime ?? 0);

  const detOrigem = fonte.detalhes_calculo || {};
  d1_block = detOrigem.d1 ?? { subcriterios: [], total: s1, gate_disparado: null };
  d2_block = detOrigem.d2 ?? { subcriterios: [], total: s2, gate_disparado: null };
  d3_block = detOrigem.d3 ?? { subcriterios: [], total: s3 };

  camposND = Array.isArray(fonte.campos_nd)
    ? fonte.campos_nd.filter((c) => c !== 'dependencia_faturamento')
    : [];

  indicadores_faltantes = Array.isArray(detOrigem.indicadores_faltantes)
  ? detOrigem.indicadores_faltantes.filter((i) => i.criterio !== 'dependencia_faturamento')
  : [];

  // S5 recalculado com as respostas recém-copiadas (não confia no s5 antigo,
  // porque o conjunto de perguntas ativas pode ter mudado desde a análise de origem).
  const contS5 = $('Contar Respostas Ativas (Reaproveitamento)').first().json;
  const totalAtivas = Number(contS5.total_ativas || 0);
  const respondidas = Number(contS5.respondidas || 0);
  const pontuando = Number(contS5.pontuando || 0);
  s5 = respondidas > 0 ? Math.round((100 * pontuando / totalAtivas) * 100) / 100 : null;
} else {
  // ---------- FLUXO NORMAL: D1/D2 vêm da coleta de API, D3 do regime recém-normalizado ----------
  const d1 = $('Executar D1 (Coleta Fiscal)').first().json;
  const d2 = $('Executar D2 (Coleta Financeira)').first().json;
  // t_pgfn e Gate G3 saem do Orquestrador (certidao do D1 + divida do Econodata matriz)
  const pgfn = $('Consolidar PGFN + Gate G3').first().json;

  const idxLongevidadeBruto = dados.data_fundacao
  ? (Date.now() - new Date(dados.data_fundacao).getTime()) / (1000 * 60 * 60 * 24 * 365.25)
  : null;
// data inválida ou no futuro = sem dado, e sem dado fica FORA da média
// (senão entraria com os pontos de ND e derrubaria a nota do subcritério)
const idxLongevidade = Number.isFinite(idxLongevidadeBruto) && idxLongevidadeBruto >= 0
  ? idxLongevidadeBruto
  : null;
const pontosLongevidade = pontosBanda('longevidade', idxLongevidade ?? 'ND');
const pontosCapital = pontosBanda('capital_social', dados.capital_social ?? 'ND');
const pontosHistoricoSocios = pontosBanda('historico_socios', dados.pct_problematico_socios ?? 'ND');
const temHistoricoSocios = dados.pct_problematico_socios != null;

const idxsObrigacoes = [
  idxLongevidade !== null ? pontosLongevidade : null,
  dados.capital_social != null ? pontosCapital : null,
  temHistoricoSocios ? pontosHistoricoSocios : null,
].filter((v) => v !== null);

const pontosObrigacoes = idxsObrigacoes.length > 0
  ? idxsObrigacoes.reduce((a, b) => a + b, 0) / idxsObrigacoes.length
  : (tabelas['historico_socios']?.nd_pontos ?? 3);

// ---- Sintonia / Confia — mesma pontuação, fontes diferentes -------------
// A pontuação continua vindo de t_sintonia ('A+' | 'ND') pela tabela ativa.
// A categoria vira texto legível dizendo QUAL programa deu o ponto.
const sintoniaFonte = d1.sintonia_fonte
  ?? (d1.t_sintonia === 'ND' ? 'nenhum' : 'selo_sintonia');  // análises antigas, sem o campo

const sintoniaCategoria =
  sintoniaFonte === 'selo_sintonia'    ? `Selo Sintonia ${d1.t_sintonia}`
  : sintoniaFonte === 'confia_protocolo' ? 'Confia · protocolo ativo'
  :                                        'Sem selo A+ e fora do Confia';

  const d1_subcriterios = [
    { criterio: 'cnd_federal', label: 'CND/CPEN Federal', categoria: d1.t_cnd, pontos: pontosOpcao('cnd_federal', d1.t_cnd) },
    { criterio: 'pgfn', label: 'Dívida ativa PGFN', categoria: pgfn.t_pgfn,
      fonte: pgfn.pgfn_fonte, divergencia: pgfn.pgfn_divergencia,
      divida_uniao_qtde: pgfn.divida_uniao_qtde,
      divida_uniao_valor_total: pgfn.divida_uniao_valor_total,
      divida_uniao_pct_faturamento: pgfn.divida_uniao_pct_faturamento,
      pontos: pontosOpcao('pgfn', pgfn.t_pgfn) },
        { criterio: 'sintonia',
      label: 'Conformidade RFB (Sintonia/Confia)',
      categoria: sintoniaCategoria,
      categoria_raw: d1.t_sintonia,      // 'A+' | 'ND' — pro front mapear badge/cor
      fonte: sintoniaFonte,              // selo_sintonia | confia_protocolo | nenhum
      pontos: pontosOpcao('sintonia', d1.t_sintonia) },
    { criterio: 'regularidade_estadual_municipal', label: 'Regularidade estadual', categoria: d1.t_est, pontos: pontosOpcao('regularidade_estadual_municipal', d1.t_est) },
        { criterio: 'obrigacoes_acessorias', label: 'Obrigações acessórias', categoria: `longevidade≈${idxLongevidade != null ? idxLongevidade.toFixed(1) + 'a' : 'ND'} · capital=${dados.capital_social ?? 'ND'} · sócios=${dados.pct_problematico_socios != null ? dados.pct_problematico_socios + '%' : 'ND'}`, pontos: pontosObrigacoes },
  ];
  s1 = d1_subcriterios.reduce((sum, s) => sum + s.pontos, 0);

  const d2_subcriterios = [
    { criterio: 'serasa_score', label: 'Serasa Score', categoria: d2.t_score, pontos: pontosBanda('serasa_score', d2.t_score) },
    { criterio: 'protestos', label: 'Protestos', categoria: d2.t_protestos, pontos: pontosBanda('protestos', d2.t_protestos) },
    { criterio: 'execucoes_relevantes', label: 'Execuções relevantes', categoria: d2.t_execucoes, pontos: pontosBanda('execucoes_relevantes', d2.t_execucoes) },
    { criterio: 'spc', label: 'Negativação SPC', categoria: d2.t_spc, pontos: pontosOpcao('spc', d2.t_spc) },
    { criterio: 'faturamento_presumido', label: 'Faturamento estimado anual', categoria: dados.faturamento_estimado ?? 'ND', pontos: pontosBanda('faturamento_presumido', dados.faturamento_estimado ?? 'ND') },
  ];
  s2 = d2_subcriterios.reduce((sum, s) => sum + s.pontos, 0);

  const regime = dados.regime_tributario || 'ND';
  s3 = pontosOpcao('regime_tributario', regime);

  d1_block = { subcriterios: d1_subcriterios, total: s1, gate_disparado: pgfn.gate_disparado ?? d1.gate_disparado,
    matriz: { cnpj_matriz: d1.cnpj_matriz, eh_filial: d1.eh_filial === true || d1.eh_filial === 'true', fonte: d1.matriz_fonte } };
  d2_block = { subcriterios: d2_subcriterios, total: s2, gate_disparado: d2.gate_disparado };
  d3_block = { subcriterios: [{ criterio: 'regime_tributario', label: 'Regime tributário', categoria: regime, pontos: s3 }], total: s3 };

  s5 = null; // D5 continua sendo calculado depois pelo workflow de recálculo
  const semObrigacoes = idxLongevidade === null && dados.capital_social == null && dados.pct_problematico_socios == null;

  // ---------- Monta camposND (compatibilidade) e indicadores_faltantes (rico) juntos ----------
  const checagens = [
    { criterio: 'cnd_federal', falhou: d1.t_cnd === 'ND', pontosAtuais: pontosOpcao('cnd_federal', d1.t_cnd) },
    { criterio: 'pgfn', falhou: pgfn.pgfn_fonte === 'divida_sem_certidao', pontosAtuais: pontosOpcao('pgfn', pgfn.t_pgfn) },
    { criterio: 'sintonia', falhou: d1.t_sintonia === 'ND', pontosAtuais: pontosOpcao('sintonia', d1.t_sintonia) },
    { criterio: 'regularidade_estadual_municipal', falhou: d1.t_est === 'ND', pontosAtuais: pontosOpcao('regularidade_estadual_municipal', d1.t_est) },
    { criterio: 'obrigacoes_acessorias', falhou: semObrigacoes, pontosAtuais: pontosObrigacoes },
    { criterio: 'serasa_score', falhou: d2.t_score === 'ND', pontosAtuais: pontosBanda('serasa_score', d2.t_score) },
    { criterio: 'protestos', falhou: d2.t_protestos === 'ND', pontosAtuais: pontosBanda('protestos', d2.t_protestos) },
    { criterio: 'execucoes_relevantes', falhou: d2.t_execucoes === 'ND', pontosAtuais: pontosBanda('execucoes_relevantes', d2.t_execucoes) },
    { criterio: 'spc', falhou: d2.t_spc === 'ND', pontosAtuais: pontosOpcao('spc', d2.t_spc) },
    { criterio: 'faturamento_presumido', falhou: dados.faturamento_estimado == null, pontosAtuais: pontosBanda('faturamento_presumido', dados.faturamento_estimado ?? 'ND') },
    { criterio: 'regime_tributario', falhou: regime === 'ND', pontosAtuais: s3 },
  ];

  for (const c of checagens) {
    if (c.falhou) {
      camposND.push(c.criterio);
      const ind = montarIndicadorFaltante(c.criterio, c.pontosAtuais);
      if (ind) indicadores_faltantes.push(ind);
    }
  }
}

// ---------- D4 — SEMPRE recalculado com o valor deste cliente ----------
const curva = tabelas['dependencia_curva'] || { p0_pct: 2, pmax_pct: 20 };
const valorPago = Number(dados.valor_compras_anual || 0);
const faturamentoFornecedor = Number(dados.faturamento_estimado || 0);
let s4, d4_nd = false, p_pct = null;
if (faturamentoFornecedor > 0) {
  p_pct = (valorPago / faturamentoFornecedor) * 100;
  const p0 = Number(curva.p0_pct ?? 2);
  const pmax = Number(curva.pmax_pct ?? 20);
  s4 = 100 * Math.max(0, Math.min(1, (pmax - p_pct) / (pmax - p0)));
  s4 = Math.round(s4 * 100) / 100;
} else {
  s4 = 50;
  d4_nd = true;
}
const d4_detalhe = {
  valor_compras_anual: valorPago,
  faturamento_estimado_fornecedor: faturamentoFornecedor || null,
  participacao_pct: p_pct !== null ? Math.round(p_pct * 100) / 100 : null,
  nd: d4_nd,
  pontos: s4,
};
if (d4_nd) camposND.push('dependencia_faturamento');

const totalCampos = 12; // 11 checagens do fluxo normal + dependencia_faturamento
const completude_pct = Math.round(((totalCampos - camposND.length) / totalCampos) * 10000) / 100;

return [{ json: {
  s1_fiscal: s1, s2_financeira: s2, s3_regime: s3, s4_dependencia: s4,
  s5_maturidade: s5,
  completude_pct, campos_nd: camposND, indicadores_faltantes,
  total_indicadores: totalCampos,
  indicadores_obtidos: totalCampos - camposND.length,
  breakdown: { d1: d1_block, d2: d2_block, d3: d3_block, d4: d4_detalhe },
  reaproveitado: !!fonte,
  fonte_reaproveitamento: fonte ? {
    analise_origem_id: fonte.analise_origem_id,
    fornecedor_origem_id: fonte.fornecedor_origem_id,
    cliente_origem_id: fonte.cliente_origem_id,
    concluido_em: fonte.concluido_em,
  } : null,
} }];

const dims = $('Montar S1-S4 e Completude').first().json;
const score = $('Executar Calcular Score').first().json;
const alertaSocios = $('Salvar Dados Cadastrais').first().json.alerta_socios === true;

const statusFinal = alertaSocios ? 'analise_manual' : score.status;
const decisaoFinal = alertaSocios ? null : score.decisao;

return [{ json: {
  s1_fiscal: dims.s1_fiscal, s2_financeira: dims.s2_financeira,
  s3_regime: dims.s3_regime, s4_dependencia: dims.s4_dependencia,
  s5_maturidade: dims.s5_maturidade,
  completude_pct: dims.completude_pct, campos_nd: dims.campos_nd,
  score_total: score.score_total, decisao: decisaoFinal, status: statusFinal,
  preliminar: score.preliminar,
  versao_pesos_id: score.versao_pesos_id, versao_thresholds_id: score.versao_thresholds_id,
  detalhes_calculo: { ...dims.breakdown, 
                     pesos_usados: score.pesos_usados, 
                     alerta_socios: alertaSocios,
                     indicadores_resumo: { total: dims.total_indicadores, obtidos: dims.indicadores_obtidos },
                    },
  reaproveitado: dims.reaproveitado,
  fonte_reaproveitamento: dims.fonte_reaproveitamento,
  indicadores_faltantes: dims.indicadores_faltantes,
} }];

