parameters.jsCode:
// ============================================================================
// CONSOLIDAR PGFN + GATE G3
//
// Antes isso vivia no D1. Migrou pra ca porque a decisao precisa de DUAS fontes
// que agora chegam em momentos diferentes:
//   • EXISTENCIA da divida  -> Econodata da MATRIZ (fonte de verdade)
//                              null/0 = nao ha divida.
//   • CLASSIFICACAO         -> CND/CPEN Federal da Infosimples (vem do D1)
//                              Só importa quando existe divida.
//
// Sem divida no Econodata, t_pgfn e 'Nao' mesmo que a certidao diga outra coisa.
// Com divida, a certidao define se e regularizada (Parcelada/garantida) ou
// exigivel (Irregular).
// ============================================================================

const d1  = $('Executar D1 (Coleta Fiscal)').first().json ?? {};
const cad = $('Normalizar Dados Cadastrais').first().json ?? {};

const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const divida_uniao_qtde            = num(cad.divida_uniao_qtde);
const divida_uniao_valor_total     = num(cad.divida_uniao_total);
const divida_uniao_pct_faturamento = num(cad.divida_uniao_pct_faturamento);

// 0 NAO conta (o Econodata devolve 0 quando nao ha divida) e null tambem nao
// (campo ausente -> assume 'Nao' por decisao da BMS).
const temDividaUniao = (divida_uniao_qtde ?? 0) > 0 || (divida_uniao_valor_total ?? 0) > 0;

// Materia-prima da certidao, vinda do D1
const cndEmitida   = d1.cnd_emitida === true || d1.cnd_emitida === 'true';
const t_cnd        = d1.t_cnd || 'ND';
const debitosPgfn  = d1.cnd_debitos_pgfn === true || d1.cnd_debitos_pgfn === 'true';
const tipo         = d1.cnd_tipo || '';

let t_pgfn = 'Não';
let pgfn_fonte = 'econodata_sem_divida';
let pgfn_divergencia = false;

if (!temDividaUniao) {
  // ---- SEM DIVIDA (null, ausente ou 0) — fonte de verdade e o Econodata ----
  t_pgfn = 'Não';
  pgfn_fonte = (divida_uniao_qtde === null && divida_uniao_valor_total === null)
    ? 'sem_dado_assumido_nao'   // Econodata nao trouxe o campo -> assume 'Nao'
    : 'econodata_sem_divida';   // veio 0 -> confirmadamente sem divida

} else if (!cndEmitida) {
  // ---- COM DIVIDA, mas a certidao nao saiu --------------------------------
  // Sem certidao nao ha como saber se esta exigivel; por decisao da BMS,
  // classifica no grau mais brando (nao penaliza por falha de coleta).
  t_pgfn = 'Parcelada/garantida';
  pgfn_fonte = 'divida_sem_certidao';

} else if (!debitosPgfn || t_cnd === 'Negativa') {
  // ---- COM DIVIDA, mas a certidao esta limpa ------------------------------
  // A certidao e do dia; a Lista de Devedores da PGFN (Econodata) e snapshot
  // trimestral. A certidao ganha, mas registra a divergencia pro analista.
  t_pgfn = 'Não';
  pgfn_fonte = 'certidao_limpa_divergente';
  pgfn_divergencia = true;

} else if (tipo.includes('efeitos de negativa')) {
  // ---- COM DIVIDA + certidao positiva c/ efeitos de negativa --------------
  t_pgfn = 'Parcelada/garantida';
  pgfn_fonte = 'cnd_efeitos_negativa';

} else {
  // ---- COM DIVIDA + certidao positiva pura --------------------------------
  t_pgfn = 'Irregular';
  pgfn_fonte = 'cnd_positiva';
}

// ---------------------------------------------------------------------------
// GATE G3 — reprovacao automatica: certidao federal POSITIVA pura + divida
// ativa irregular. Avaliado aqui, ANTES do D2, pra nao gastar Serasa em
// fornecedor que ja esta reprovado.
// ---------------------------------------------------------------------------
const gate_disparado = (t_cnd === 'Positiva' && t_pgfn === 'Irregular')
  ? 'G3: CND federal positiva + PGFN irregular'
  : (d1.gate_disparado || null);

return [{
  json: {
    t_pgfn,
    pgfn_fonte,          // econodata_sem_divida | sem_dado_assumido_nao | divida_sem_certidao
                         // | certidao_limpa_divergente | cnd_efeitos_negativa | cnd_positiva
    pgfn_divergencia,    // true = certidao limpa mas Econodata acusa divida
    divida_uniao_qtde,
    divida_uniao_valor_total,
    divida_uniao_pct_faturamento,
    gate_disparado,
    cnpj_matriz: cad.cnpj_matriz ?? null,
  }
}];

