let nomeS = 'Desconhecido', documentoS = null, ativas = 0, baixadas = 0, inaptas = 0, total = 0;

// Fallback: quando o node de Vínculos Societários está desabilitado ou falhou,
// $json ainda é o próprio contato vindo da Econodata (nome / cpf / qualificação).
try {
  const resp = $json;
  const rel = resp?.retorno ?? null;

  nomeS = rel?.nomeEntidade ?? resp?.nome ?? 'Desconhecido';
  documentoS = rel?.documentoConsultado
    ?? (resp?.cpf ? String(resp.cpf).replace(/\D/g, '') : null);

  // CPF mascarado (ex.: ***.123.456-**) não serve como documento válido
  if (documentoS && documentoS.length !== 11 && documentoS.length !== 14) documentoS = null;

  if (rel && Array.isArray(rel.relacionamentos)) {
    for (const r of rel.relacionamentos) {
      if (r.nivel !== 1) continue;
      if (r.tipo !== 'Sociedade') continue;
      const pj = r.detalhesPessoaJuridica;
      if (!pj) continue;
      total++;
      if (pj.baixada === true) baixadas++;
      else if (pj.situacaoCadastral === 'ATIVA') ativas++;
      else inaptas++;
    }
  }
} catch (e) {
  // Qualquer formato inesperado -> sócio conta como "sem dado", nunca dispara alerta por engano.
}

// Sem consulta de vínculos = sem dado. Zera o documento para o agregador ignorar
// este sócio no cálculo do pct médio (senão entraria como 0% problemático).
if (total === 0) documentoS = null;

const pctProblematico = total > 0 ? Math.round(((baixadas + inaptas) / total) * 10000) / 100 : 0;

return { json: { nome: nomeS, documento: documentoS, total, ativas, baixadas, inaptas, pct_problematico: pctProblematico } };

const items = $input.all().map(item => item.json);
const reais = items.filter(s => !!s.documento); // exclui o fallback "sem sócios" e sócios cuja consulta falhou

const pctMedio = reais.length > 0
  ? Math.round((reais.reduce((sum, s) => sum + s.pct_problematico, 0) / reais.length) * 100) / 100
  : null; // null = nenhum sócio com dado disponível (ND)

return [{ json: { pct_problematico_medio: pctMedio, detalhes_socios: items }, pairedItem: 0 }];

const retorno = $json.retorno ?? {};
const socios = Array.isArray(retorno.socios) ? retorno.socios : [];

function parseData(str) {
  if (!str) return null;
  const s = String(str).trim().split(' ')[0];
  let d;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) d = new Date(s);
  else if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
    const [dd, mm, yyyy] = s.split('/');
    d = new Date(`${yyyy}-${mm}-${dd}`);
  } else return null;
  const t = d.getTime();
  return Number.isFinite(t) ? t : null;
}

// ordena por data de entrada na sociedade (mais antigos primeiro).
// sócios sem data válida vão pro fim — nunca entram no top 3 por acidente.
const ordenados = [...socios].sort((a, b) => {
  const ta = parseData(a.dataEntradaSociedade);
  const tb = parseData(b.dataEntradaSociedade);
  if (ta === null && tb === null) return 0;
  if (ta === null) return 1;
  if (tb === null) return -1;
  return ta - tb;
});

const top3 = new Set(ordenados.slice(0, 3));

const socios_marcados = socios.map(s => ({
  ...s,
  verificar_vinculos: top3.has(s)
}));

return [{
  json: {
    ...$json,
    retorno: { ...retorno, socios: socios_marcados }
  }
}];

return [{ json: {
  nome: $json.nome ?? 'Desconhecido',
  documento: null, // não verificado -> excluído do cálculo do pct médio
  total: 0, ativas: 0, baixadas: 0, inaptas: 0, pct_problematico: 0,
  verificacao: 'fora do top 3 mais antigos — vínculos não checados'
} }];

return [{ json: {
  indicadores_faltantes: $('Montar Resultado Final').item.json.indicadores_faltantes
} }];

// O CNPJ consultado JA E a matriz — reaproveita a 1a chamada do Econodata
// em vez de gastar um segundo credito com o mesmo CNPJ.
return [{ json: $('Econodata · Empresa (Consultado)').first().json }];

// Ponto unico de referencia pro Econodata da MATRIZ, venha ele da 2a chamada
// (CNPJ era filial) ou do reaproveitamento da 1a (CNPJ ja era a matriz).
// So um dos dois ramos roda, entao so um item chega aqui.
return [{ json: $json }];

